hypotheses_and_conclusion:
(hn : 0 < n) {y : Fin n → ℝ}
    (hne : ∃ i j, y i ≠ y j) :
    ∃ c > 0, ∃ b, ∀ d > 0, ∀ a, weibullLik y d a ≤ weibullLik y c b

(hn : 0 < n) {y : Fin n → ℝ}
    (hne : ∃ i j, y i ≠ y j) {W : ℝ}
    (hW : ∀ c > 0, ∀ b, weibullLik y c b ≤ W)
    {k c b : ℝ} (hk : 0 < k) (hc : 0 < c) (hlarge : 2 * (n : ℝ) ≤ k) :
    likelihood y (k,c,b) ≤ W + 2 * (n : ℝ)^2/k
